import datetime
import numpy as np
import matplotlib.pyplot as plt

# Constants
TIME_FORMAT = "%d/%m/%y %H:%M:%S.%f"

def task_func(time_strings):
    parsed_dates = [
        datetime.datetime.strptime(ts, TIME_FORMAT)
        for ts in time_strings
    ]

    diffs = [
        int((parsed_dates[i + 1] - parsed_dates[i]).total_seconds())
        for i in range(len(parsed_dates) - 1)
    ]

    fig, ax = plt.subplots()
    ax.bar(np.arange(len(diffs)), diffs)

